target.css:
:root {
  --ink: #20323a;
  --muted: #65767b;
  --paper: #fffdf7;
  --soft: #f1f5ef;
  --line: #d8e0d9;
  --mint: #cce8d7;
  --green: #28785d;
  --orange: #e77c45;
  --orange-soft: #fff0e7;
  --white: #ffffff;
}

* {
  box-sizing: border-box;
}

.panel {
  width: 500px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.topbar {
  display: flex;
  align-items: center;
  min-height: 64px;
  padding: 11px 16px;
  gap: 10px;
  border-bottom: 1px solid var(--line);
}

.mark {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  color: var(--paper);
  background: var(--green);
  border-radius: 10px;
  font-size: 18px;
}

.title-block {
  flex: 1;
  min-width: 0;
}

.eyebrow {
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 1px;
  line-height: 1.2;
}

.panel h1,
.panel h2,
.panel p {
  margin: 0;
}

.title-block h1 {
  margin-top: 3px;
  font-size: 19px;
  font-weight: 750;
  letter-spacing: -0.35px;
  line-height: 1.1;
}

.mode,
.count {
  color: var(--green);
  background: var(--mint);
  border-radius: 999px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.8px;
}

.mode {
  padding: 6px 8px;
}

.content {
  display: grid;
  grid-template-columns: 166px 1fr;
  min-height: 164px;
}

.machine {
  display: flex;
  flex-direction: column;
  padding: 15px;
  background: var(--soft);
  border-right: 1px solid var(--line);
}

.machine h2 {
  margin-top: 4px;
  font-size: 17px;
  line-height: 1.15;
}

.state {
  display: flex;
  align-items: center;
  width: max-content;
  margin-top: 8px;
  gap: 5px;
  color: var(--green);
  font-size: 11px;
  font-weight: 700;
}

.state i {
  width: 7px;
  height: 7px;
  background: var(--green);
  border-radius: 50%;
}

.metrics {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  margin: auto 0 0;
}

.metrics div {
  padding-left: 7px;
  border-left: 1px solid var(--line);
}

.metrics div:first-child {
  padding-left: 0;
  border-left: 0;
}

.metrics dt {
  color: var(--muted);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.5px;
}

.metrics dd {
  margin: 3px 0 0;
  font-size: 12px;
  font-weight: 750;
}

.queue {
  padding: 14px 15px;
}

.queue-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 8px;
}

.queue-head h2 {
  font-size: 14px;
  letter-spacing: -0.15px;
}

.count {
  padding: 4px 6px;
  background: var(--soft);
}

.jobs {
  padding: 0;
  margin: 0;
  list-style: none;
}

.job {
  display: grid;
  grid-template-columns: 25px minmax(0, 1fr) auto;
  align-items: center;
  min-height: 31px;
  padding: 4px 7px;
  gap: 7px;
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 8px;
}

.job + .job {
  margin-top: 5px;
}

.job.current {
  background: var(--orange-soft);
  border-color: var(--orange);
}

.job-symbol {
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
}

.current .job-symbol {
  color: var(--orange);
}

.job-copy {
  display: flex;
  align-items: baseline;
  min-width: 0;
  gap: 6px;
}

.job-copy strong {
  overflow: hidden;
  font-size: 11px;
  font-weight: 750;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.job-copy span {
  color: var(--muted);
  font-size: 9px;
  white-space: nowrap;
}

.job time {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
}

.footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 43px;
  padding: 8px 16px;
  background: var(--soft);
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 11px;
}

.footer b {
  color: var(--green);
  font-size: 12px;
}

.footer button {
  padding: 0;
  color: var(--ink);
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: 7px;
  font-size: 10px;
  font-weight: 750;
  line-height: 25px;
  padding-inline: 8px;
}

.footer button span {
  margin-left: 4px;
  color: var(--green);
  font-size: 13px;
}

